import * as React from 'react';
import { styled, useTheme } from '@mui/material/styles';
import Box from '@mui/material/Box';
import Drawer from '@mui/material/Drawer';
import CssBaseline from '@mui/material/CssBaseline';
import MuiAppBar from '@mui/material/AppBar';
import Toolbar from '@mui/material/Toolbar';   
import List from '@mui/material/List';
import Typography from '@mui/material/Typography';
import Divider from '@mui/material/Divider';
import IconButton from '@mui/material/IconButton';
import MenuIcon from '@mui/icons-material/Menu';
import ChevronLeftIcon from '@mui/icons-material/ChevronLeft';
import ChevronRightIcon from '@mui/icons-material/ChevronRight';
import ListItem from '@mui/material/ListItem';
import ListItemButton from '@mui/material/ListItemButton';
import ListItemIcon from '@mui/material/ListItemIcon';
import ListItemText from '@mui/material/ListItemText';
import InboxIcon from '@mui/icons-material/MoveToInbox';
import MailIcon from '@mui/icons-material/Mail';
import DashboardCustomizeIcon from '@mui/icons-material/DashboardCustomize';
import { Link } from 'react-router-dom';
import Collapse from "@mui/material/Collapse";
import ExpandLess from "@mui/icons-material/ExpandLess";
import ExpandMore from "@mui/icons-material/ExpandMore";

const drawerWidth = 240;

const Main = styled('main', { shouldForwardProp: (prop) => prop !== 'open' })(
  ({ theme }) => ({
    flexGrow: 1,
    padding: theme.spacing(3),
    marginLeft: `-${drawerWidth}px`,
  }),
);

const AppBar = styled(MuiAppBar)(({ theme }) => ({
  transition: theme.transitions.create(['margin', 'width']),
}));

const DrawerHeader = styled('div')(({ theme }) => ({
  display: 'flex',
  alignItems: 'center',
  padding: theme.spacing(0, 1),
  ...theme.mixins.toolbar,
  justifyContent: 'flex-end',
}));

export default function ManageUser() {

  const theme = useTheme();
  const [open, setOpen] = React.useState(false);
    
  const handleUsersClick = () => {
    setOpen(!open);
  };
  const handleDrawerOpen = () => {
    setOpen(true);
  };

  const handleDrawerClose = () => {
    setOpen(false);
  };

  return (

    <Box sx={{ display: 'flex' }}>
      <CssBaseline />

      <AppBar position="fixed" open={open}>
        <Toolbar>

          <IconButton
            color="inherit"
            aria-label="open drawer"
            onClick={handleDrawerOpen}
            edge="start"
          >
            <MenuIcon />
          </IconButton>

          <Typography variant="h6" noWrap component="div">
            Loreseum
          </Typography>

        </Toolbar>
      </AppBar>

      <Drawer
        sx={{
          width: drawerWidth,
          flexShrink: 0,
          '& .MuiDrawer-paper': {
            width: drawerWidth,
            boxSizing: 'border-box',
          },
        }}

        variant="persistent"
        anchor="left"
        open={open}
      >

        <DrawerHeader>

          <IconButton onClick={handleDrawerClose}>
            {theme.direction === 'ltr' ? <ChevronLeftIcon /> : <ChevronRightIcon />}
          </IconButton>

        </DrawerHeader>

        <Divider />

        <List>

          <ListItem disablePadding>
            <ListItemButton component={Link} to="/Admin/Dashboard">
              <ListItemIcon>
                <DashboardCustomizeIcon />
              </ListItemIcon>
              <ListItemText primary="Dashboard" />
            </ListItemButton>
          </ListItem>

<ListItem disablePadding>
  <ListItemButton onClick={handleUsersClick}>
    <ListItemIcon>
      <InboxIcon />
    </ListItemIcon>

    <ListItemText primary="Users" />

    {open ? <ExpandLess /> : <ExpandMore />}
  </ListItemButton>
</ListItem>

<Collapse in={open} timeout="auto" unmountOnExit>
  <List component="div" disablePadding>

    <ListItem disablePadding sx={{ pl: 4 }}>
      <ListItemButton component={Link} to="/Admin/ViewUser">
        <ListItemText primary="View Users" />
      </ListItemButton>
    </ListItem>

    <ListItem disablePadding sx={{ pl: 4 }}>
      <ListItemButton component={Link} to="/Admin/AddUser">
        <ListItemText primary="Add Users" />
      </ListItemButton>
    </ListItem>

  </List>
</Collapse>
<ListItem disablePadding>
  <ListItemButton onClick={handleUsersClick}>
    <ListItemIcon>
      <InboxIcon />
    </ListItemIcon>

    <ListItemText primary="Category" />

    {open ? <ExpandLess /> : <ExpandMore />}
  </ListItemButton>
</ListItem>

<Collapse in={open} timeout="auto" unmountOnExit>
  <List component="div" disablePadding>

    <ListItem disablePadding sx={{ pl: 4 }}>
      <ListItemButton component={Link} to="/Admin/AddCategory">
        <ListItemText primary="Add Category" />
      </ListItemButton>
    </ListItem>

    <ListItem disablePadding sx={{ pl: 4 }}>
      <ListItemButton component={Link} to="/Admin/ViewCategory">
        <ListItemText primary="View category" />
      </ListItemButton>
    </ListItem>

  </List>
</Collapse>
        </List>

        <Divider />

        <List>

          {[ 'Price', 'Vehicle','View Booking', 'Payment', 'Feedback'].map((text, index) => (

            <ListItem key={text} disablePadding>

              <ListItemButton>

                <ListItemIcon>
                  {index % 2 === 0 ? <InboxIcon /> : <MailIcon />}
                </ListItemIcon>

                <ListItemText primary={text} />

              </ListItemButton>

            </ListItem>

          ))}

        </List>

      </Drawer>

      <Main open={open}>

        <DrawerHeader />

        <Typography sx={{ marginBottom: 2 }}>
          Lorem ipsum dolor sit amet consectetur adipisicing elit. Laudantium quidem inventore labore necessitatibus molestias maiores et, saepe aliquid recusandae blanditiis assumenda magni, delectus sapiente iusto qui iure nesciunt, officia laboriosam.
          Lorem ipsum dolor sit amet, consectetur adipisicing elit. In earum quidem repellat quis. Facilis magnam exercitationem nesciunt quo. Soluta nisi unde suscipit eligendi sint earum accusantium perspiciatis laborum beatae molestiae.
        </Typography>

      </Main>

    </Box>

  );

}